```javascript
// Импортируем необходимые модули
const { Builder, By, until } = require('selenium-webdriver');

// Настройка драйвера (например, Chrome)
(async function example() {
    let driver = await new Builder()
        .forBrowser('chrome')
        .build();

    try {
        // Открываем веб-сайт
        await driver.get('http://ваш-веб-сайт.com');

        // Ждем, пока элемент станет видимым
        await driver.wait(until.elementLocated(By.id('ваш-идентификатор-элемента')), 10000);

        // Взаимодействуем с элементом (например, нажимаем кнопку)
        let element = await driver.findElement(By.id('ваш-идентификатор-кнопки'));
        await element.click();

        // Проверяем, что элемент появился или исчез
        await driver.wait(until.elementIsNotVisible(element), 5000);

        console.log('Тест прошел успешно!');
    } finally {
        // Закрываем браузер
        await driver.quit();
    }
})();
```

